    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int r = (int) in.nval;
        in.nextToken();
        int c = (int) in.nval;
        long[][] grid = new long[r][c];
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++) {
                in.nextToken();
                grid[i][j] = (long) in.nval;
            }
        sortMatrix(grid);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) sb.append(grid[i][j]).append(j + 1 < c ? " " : "\n");
        }
        System.out.print(sb);
    }
}
